renderUI();setInterval(()=>{if(game.energy===0&&game.place==='cabin'){$('#sceneHint').textContent='YOU DESERVE A REST · PRESS R OR CLICK REST';}},1000);

// Free-roam controls, scene interactions, and gentle hands-on kitchen activities.
game.player=game.player||{};game.stats={recipes:0,drinks:0,harvests:0,...(game.stats||{})};game.achievements=game.achievements||[];
const places=Object.keys(locations);const homePositions={cabin:{x:350,y:296},garden:{x:320,y:316},woods:{x:318,y:318},market:{x:320,y:315},backyard:{x:320,y:330}};
function playerPosition(){if(!game.player[game.place])game.player[game.place]={...homePositions[game.place]};return game.player[game.place]}
const sceneObjects={cabin:[{x:320,y:191,name:'Kitchen stove',run:()=>cook()},{x:207,y:252,name:'Woodpile',run:()=>chop()},{x:414,y:251,name:'Your companion',run:()=>petAction('pet')},{x:320,y:276,name:'Cozy living room',run:()=>movie()}],garden:[{x:320,y:270,name:'Garden beds',run:()=>gardenMenu()},{x:546,y:100,name:'Garden sign',run:()=>openJournal('The garden')}],woods:[{x:315,y:278,name:'Mossy path',run:()=>forage()},{x:472,y:282,name:'Ferny clearing',run:()=>explore()}],market:[{x:320,y:221,name:'Fern & Fable counter',run:()=>shop('supplies')},{x:468,y:219,name:'Homewares shelf',run:()=>shop('home')}],backyard:[{x:320,y:297,name:'Firepit',run:()=>fire()},{x:323,y:239,name:'Projector',run:()=>movie(true)},{x:390,y:306,name:'S’mores basket',run:()=>smores()}]};
function drawPlayer(){const p=playerPosition(),x=Math.round(p.x),y=Math.round(p.y);ctx.globalAlpha=.22;ctx.fillStyle='#283b32';ctx.beginPath();ctx.ellipse(x,y+1,9,3,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;rect(x-6,y-19,12,10,'#d7b88d');rect(x-7,y-10,14,13,'#789273');rect(x-8,y+2,6,7,'#675445');rect(x+2,y+2,6,7,'#675445');rect(x-8,y-22,16,5,'#5d5142');px(x-4,y-15,'#405245',2);px(x+3,y-15,'#405245',2)}
const originalSceneRender=sceneRender;sceneRender=function(){originalSceneRender();drawPlayer()};
function announceAchievement(id,title,detail){if(game.achievements.includes(id))return;game.achievements.push(id);toast(`New keepsake: ${title} ✨`);game.lastAchievement=detail}
function openJournal(title='A page from your journal'){let season=['Spring','Summer','Autumn','Winter'][Math.floor((game.day-1)/7)%4];const pages=[`Day ${game.day} · ${season}`,`Places visited: ${Object.keys(game.visited||{}).join(', ')||'The cabin'}`,`Little companions: ${game.cats.map(c=>c.name).join(' and ')}`,`Harvests: ${game.stats.harvests} · recipes: ${game.stats.recipes} · coffees: ${game.stats.drinks}`,`Keepsakes: ${game.achievements.length?game.achievements.join(' · '):'Your story is just beginning'}`];openModal(title,'A few things you might like to remember.',[{emoji:'📖',name:'Today, in a few words',desc:pages.join('  ·  '),cost:'KEEP'}],'This journal is yours. The quiet days count, too.')}
function gardenMenu(){openModal('A little garden time','Choose a gentle thing to do among the beds.',[{emoji:'🌰',name:'Plant seeds',desc:'Give a new row a place to grow.',run:()=>{closeModal();plant()}},{emoji:'🧺',name:'Harvest',desc:'Gather anything that is ready.',run:()=>{closeModal();harvest()}},{emoji:'🌿',name:'Tend the beds',desc:'Pull weeds and gather fresh herbs.',run:()=>{closeModal();tend()}}])}
function getSeason(){return ['Spring','Summer','Autumn','Winter'][Math.floor((game.day-1)/7)%4]}
function getWeather(){return ['clear skies','soft rain','cloudy','golden sunshine','misty'][((game.day*7+Math.floor(game.day/3))%5)]}
const originalRenderUI=renderUI;renderUI=function(){originalRenderUI();let season=getSeason(),weather=getWeather(),temp=[17,23,12,3][['Spring','Summer','Autumn','Winter'].indexOf(season)];$('.weather b').textContent=season;$('.weather small').textContent=`Day ${String(game.day).padStart(2,'0')} · ${temp}°C · ${weather}`;$('#sceneHint').textContent='WASD / ARROWS TO WANDER · E TO INTERACT · CLICK TO WALK';$$('.rail-btn[data-place]').forEach(b=>b.classList.toggle('active',b.dataset.place===game.place))};
const originalGo=go;go=function(place){originalGo(place);game.visited=game.visited||{};game.visited[place]=true;if(Object.keys(game.visited).length>=3)announceAchievement('wanderer','Little Wanderer','Visited three places');save()};
function nearObject(){const p=playerPosition();return sceneObjects[game.place].map(o=>({...o,d:Math.hypot(o.x-p.x,o.y-p.y)})).sort((a,b)=>a.d-b.d)[0]}
function interact(){const o=nearObject();if(o&&o.d<65){o.run();return}toast('Wander a little closer to a spot that catches your eye.');}
function moveTo(x,y,auto=false){const p=playerPosition();p.tx=Math.max(16,Math.min(624,x));p.ty=Math.max(25,Math.min(345,y));p.auto=auto}
function tickWalk(){let p=playerPosition();if(p.tx==null)return;let dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy),step=Math.min(3.2,d);if(d<2){p.x=p.tx;p.y=p.ty;delete p.tx;delete p.ty;if(p.auto){delete p.auto;interact()}save();return}p.x+=dx/d*step;p.y+=dy/d*step;sceneRender()}
setInterval(tickWalk,24);
const moveKeys={ArrowUp:[0,-1],w:[0,-1],W:[0,-1],ArrowDown:[0,1],s:[0,1],S:[0,1],ArrowLeft:[-1,0],a:[-1,0],A:[-1,0],ArrowRight:[1,0],d:[1,0],D:[1,0]};
document.addEventListener('keydown',e=>{if($('#modalRoot').innerHTML)return;if(moveKeys[e.key]){e.preventDefault();const p=playerPosition(),v=moveKeys[e.key];p.tx=Math.max(12,Math.min(628,(p.tx??p.x)+v[0]*36));p.ty=Math.max(20,Math.min(350,(p.ty??p.y)+v[1]*36));p.auto=false}else if(e.key.toLowerCase()==='e'){e.preventDefault();interact()}});
canvas.addEventListener('click',e=>{if($('#modalRoot').innerHTML)return;e.preventDefault();e.stopImmediatePropagation();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*640/r.width,y=(e.clientY-r.top)*360/r.height;const o=sceneObjects[game.place].map(o=>({...o,d:Math.hypot(o.x-x,o.y-y)})).sort((a,b)=>a.d-b.d)[0];if(o&&o.d<44)moveTo(o.x,o.y,true);else moveTo(x,y,false)},true);
function addTouchPad(){const wrap=$('.scene-wrap');if(!wrap||$('#walkPad'))return;const pad=document.createElement('div');pad.id='walkPad';pad.className='walk-pad';pad.setAttribute('aria-label','Movement controls');[['↑',0,-1],['←',-1,0],['↓',0,1],['→',1,0]].forEach(([label,dx,dy])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',`Walk ${label}`);b.onclick=()=>{const p=playerPosition();p.tx=Math.max(12,Math.min(628,p.x+dx*50));p.ty=Math.max(20,Math.min(350,p.y+dy*50));p.auto=false};pad.append(b)});const use=document.createElement('button');use.className='walk-use';use.textContent='E';use.title='Interact nearby';use.onclick=interact;pad.append(use);wrap.append(pad)}addTouchPad();
const originalCook=cook,originalDrink=drink;
function kitchenModal(title,subtitle,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal kitchen-modal" role="dialog" aria-modal="true"><div class="modal-top"><div><div class="eyebrow">A HANDS-ON LITTLE RITUAL</div><h2>${title}</h2><p>${subtitle}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="kitchen-content">${body}</div><div class="modal-foot"><span>Take your time. You can close this whenever you like.</span><strong>✦ ${game.points} drops</strong></div></section></div>`;$('#modalRoot .modal-close').onclick=closeModal;$('#modalRoot .modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function startKitchenGame(kind,recipe){const espresso=kind==='espresso',state={step:0,prep:0,bar:0,direction:1,started:false,quality:0};const stages=espresso?['Grind the beans','Tamp the grounds','Pull the espresso']:['Gather your ingredients','Prepare the batter','Cook it just right'];function show(){let step=state.step;let content='';if(step<2){content=`<div class="ritual-scene"><span>${espresso?['☕','⚙️','🫘'][step]:recipe.emoji}</span></div><p class="ritual-instruction">${stages[step]}</p><p class="ritual-sub">${espresso?(step===0?'Tap the grinder three times to get a fine, even grind.':'Press down once to tamp your coffee bed.'):(step===0?'Tap each ingredient to set it on the counter.':'Stir the bowl three times until the batter is smooth.')}</p><div class="prep-dots">${Array.from({length:espresso&&step===1?1:3},(_,i)=>`<i class="${i<state.prep?'filled':''}"></i>`).join('')}</div><button class="ritual-button" id="ritualNext">${state.prep>=(espresso&&step===1?0:3)?'Continue →':'Tap to prepare'}</button>`}else if(step===2){content=`<div class="ritual-scene"><span>${espresso?'☕':'🍳'}</span></div><p class="ritual-instruction">${espresso?'Find the sweet spot':'A little golden, not too long'}</p><p class="ritual-sub">Press <b>Stop</b> while the marker is in the green zone.</p><div class="timing-track"><i class="sweet-spot"></i><span id="timingMarker" style="left:0%"></span></div><button class="ritual-button" id="ritualStop">Stop the pour</button>`}else{content=`<div class="ritual-scene"><span>${espresso?'🧋':recipe.emoji}</span></div><p class="ritual-instruction">${state.quality>=2?'Lovely timing!':'Made with care'}</p><p class="ritual-sub">${espresso?'Your espresso is silky, fragrant, and ready to enjoy.':`${recipe.name} is ready, with a little portion for your companion.`}</p><button class="ritual-button" id="ritualServe">Serve it up ♡</button>`}
kitchenModal(espresso?'Your espresso, step by step':recipe.name,`STEP ${Math.min(step+1,3)} OF 3 · ${stages[Math.min(step,2)]}`,content);if(step<2){$('#ritualNext').onclick=()=>{const needed=espresso&&step===1?1:3;if(state.prep<needed){state.prep++;show()}else{state.step++;state.prep=0;show()}}}else if(step===2){let marker=$('#timingMarker');const timer=setInterval(()=>{if(!marker?.isConnected){clearInterval(timer);return}state.bar+=state.direction*2.7;if(state.bar>=100||state.bar<=0)state.direction*=-1;marker.style.left=`${state.bar}%`},28);$('#ritualStop').onclick=()=>{clearInterval(timer);state.quality=state.bar>=40&&state.bar<=64?3:state.bar>=25&&state.bar<=78?2:1;state.step=3;show()}}else $('#ritualServe').onclick=()=>finishKitchenGame(kind,recipe,state.quality)}show()}
function finishKitchenGame(kind,recipe,quality){if(!spend()){closeModal();return}if(kind==='espresso'){consume({Beans:1});game.points+=10+quality*2;game.stats.drinks++;complete('drink');toast(`A lovely espresso, poured just right. +${10+quality*2} drops`)}else{consume(recipe.cost);game.inventory['Cat food']=(game.inventory['Cat food']||0)+1;game.points+=recipe.reward+quality*2;game.stats.recipes++;complete(recipe.task);toast(`${recipe.name} is ready! A little portion for ${game.cats[game.cat].name}. +${recipe.reward+quality*2} drops`)}if(game.stats.recipes>=5)announceAchievement('homecook','Home Kitchen','Made five recipes');closeModal();save()}
cook=function(){const choices=recipes.filter(r=>r.name!=='Iced honey oat latte');openModal('What sounds good?','Choose a recipe, then make it with your own hands.',choices.map(r=>({emoji:r.emoji,name:r.name,desc:r.desc,cost:canPay(r.cost)?Object.entries(r.cost).map(([k,v])=>`${v} ${k}`).join(' · '):'Need '+Object.keys(r.cost).filter(k=>(game.inventory[k]||0)<r.cost[k]).join(', '),disabled:!canPay(r.cost),run:()=>{closeModal();startKitchenGame('cook',r)}})),'Gather ingredients · prepare · watch the pan. Cooking uses 1 energy when you serve.')};
drink=function(){openModal('A little coffee ritual','A specialty drink, one small step at a time.',[{emoji:'🧋',name:'Honey oat iced espresso',desc:'Grind, tamp, and pull a silky little shot.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{closeModal();startKitchenGame('espresso')}},{emoji:'☕',name:'Pour-over, slow & easy',desc:'A warm cup for a thoughtful morning.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{closeModal();startKitchenGame('espresso')}}])};

